"""
Multi-tenant FastAPI app on a single SQLite database.

Isolation model:
  * Every table carries a ``tenant_id`` column.
  * The tenant is resolved from the ``X-Tenant-ID`` header by the
    ``get_scoped_db`` dependency (401 if missing, 403 if unknown).
  * Handlers never touch the raw connection. They receive a ``ScopedDB``
    whose ``execute()`` refuses to run any statement that does not carry
    the mandatory ``{tenant}`` scope marker -- so a query physically
    cannot be written without a tenant filter.
"""
from __future__ import annotations

import sqlite3
from contextlib import closing
from typing import Any, Iterator

from fastapi import Depends, FastAPI, Header, HTTPException, Request, status
from pydantic import BaseModel, Field

DB_PATH = "app.db"

# Marker that must appear in every statement passed to ScopedDB.execute().
# It is substituted with a bound parameter for the resolved tenant_id.
SCOPE_MARKER = "{tenant}"
_SCOPE_PARAM = "__scope_tenant_id__"


# --------------------------------------------------------------------------- #
# Schema / bootstrap
# --------------------------------------------------------------------------- #
SCHEMA = """
CREATE TABLE IF NOT EXISTS tenants (
    tenant_id TEXT PRIMARY KEY,
    name      TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS customers (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    tenant_id TEXT NOT NULL REFERENCES tenants(tenant_id),
    name      TEXT NOT NULL,
    email     TEXT NOT NULL
);
"""


def connect(path: str = DB_PATH) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db(path: str = DB_PATH, tenants: tuple[str, ...] = ("acme", "globex", "initech")) -> None:
    with closing(connect(path)) as conn:
        conn.executescript(SCHEMA)
        conn.executemany(
            "INSERT OR IGNORE INTO tenants (tenant_id, name) VALUES (?, ?)",
            [(t, t.title()) for t in tenants],
        )
        conn.commit()


# --------------------------------------------------------------------------- #
# Tenant-scoped database handle
# --------------------------------------------------------------------------- #
class UnsafeQuery(Exception):
    """Raised when a statement lacks the mandatory tenant-scope marker."""


class ScopedDB:
    """Thin wrapper around a sqlite3 connection bound to one tenant.

    Every statement MUST contain ``{tenant}`` inside its WHERE clause;
    the marker is replaced by a bound parameter pinned to the tenant
    resolved from the request. There is no way to issue an unscoped
    statement through this object.
    """

    def __init__(self, conn: sqlite3.Connection, tenant_id: str) -> None:
        self._conn = conn
        self.tenant_id = tenant_id

    def execute(self, sql: str, params: Sequence | None = None) -> sqlite3.Cursor:
        if SCOPE_MARKER not in sql:
            raise UnsafeQuery(
                "refusing to run a statement without a {tenant} scope marker"
            )
        scoped_sql = sql.replace(SCOPE_MARKER, f":{_SCOPE_PARAM}")
        bound = dict(params or {})
        if _SCOPE_PARAM in bound:
            raise UnsafeQuery("parameter name collides with internal scope parameter")
        bound[_SCOPE_PARAM] = self.tenant_id
        return self._conn.execute(scoped_sql, bound)

    def commit(self) -> None:
        self._conn.commit()

    def rollback(self) -> None:
        self._conn.rollback()

    def close(self) -> None:
        self._conn.close()

    # Convenience helpers ---------------------------------------------------
    def fetchone(self, sql: str, params: dict[str, Any] | None = None) -> sqlite3.Row | None:
        return self.execute(sql, params).fetchone()

    def fetchall(self, sql: str, params: dict[str, Any] | None = None) -> list[sqlite3.Row]:
        return self.execute(sql, params).fetchall()


from typing import Sequence  # noqa: E402  (used in annotation above)


# --------------------------------------------------------------------------- #
# Dependencies
# --------------------------------------------------------------------------- #
def get_scoped_db(
    x_tenant_id: str | None = Header(default=None),
) -> Iterator[ScopedDB]:
    """Resolve the tenant and yield a ScopedDB pinned to it."""
    if x_tenant_id is None or x_tenant_id.strip() == "":
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Missing X-Tenant-ID header",
            headers={"WWW-Authenticate": "Tenant"},
        )
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant_id FROM tenants WHERE tenant_id = ?", (x_tenant_id,)
        ).fetchone()
        if row is None:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail=f"Unknown tenant '{x_tenant_id}'",
            )
        db = ScopedDB(conn, x_tenant_id)
        try:
            yield db
        except Exception:
            db.rollback()
            raise
    finally:
        conn.close()


# --------------------------------------------------------------------------- #
# Models & app
# --------------------------------------------------------------------------- #
class CustomerIn(BaseModel):
    name: str = Field(min_length=1)
    email: str


class CustomerUpdate(BaseModel):
    name: str | None = None
    email: str | None = None


app = FastAPI(title="Multi-tenant customers API")


@app.post("/customers", status_code=status.HTTP_201_CREATED)
def create_customer(payload: CustomerIn, db: ScopedDB = Depends(get_scoped_db)) -> dict:
    cur = db.execute(
        "INSERT INTO customers (tenant_id, name, email) "
        f"VALUES ({SCOPE_MARKER}, :name, :email)",
        {"name": payload.name, "email": payload.email},
    )
    db.commit()
    return {"id": cur.lastrowid, "name": payload.name, "email": payload.email}


@app.get("/customers")
def list_customers(db: ScopedDB = Depends(get_scoped_db)) -> list[dict]:
    rows = db.fetchall(f"SELECT id, name, email FROM customers WHERE tenant_id = {SCOPE_MARKER}")
    return [dict(r) for r in rows]


@app.get("/customers/{customer_id}")
def get_customer(customer_id: int, db: ScopedDB = Depends(get_scoped_db)) -> dict:
    row = db.fetchone(
        f"SELECT id, name, email FROM customers WHERE id = :id AND tenant_id = {SCOPE_MARKER}",
        {"id": customer_id},
    )
    if row is None:
        raise HTTPException(status_code=404, detail="Customer not found")
    return dict(row)


@app.patch("/customers/{customer_id}")
def update_customer(
    customer_id: int, payload: CustomerUpdate, db: ScopedDB = Depends(get_scoped_db)
) -> dict:
    fields = payload.model_dump(exclude_unset=True)
    if not fields:
        raise HTTPException(status_code=422, detail="No fields to update")
    set_clause = ", ".join(f"{col} = :{col}" for col in fields)
    cur = db.execute(
        f"UPDATE customers SET {set_clause} WHERE id = :id AND tenant_id = {SCOPE_MARKER}",
        {**fields, "id": customer_id},
    )
    if cur.rowcount == 0:
        db.rollback()
        raise HTTPException(status_code=404, detail="Customer not found")
    db.commit()
    return dict(
        db.fetchone(
            f"SELECT id, name, email FROM customers WHERE id = :id AND tenant_id = {SCOPE_MARKER}",
            {"id": customer_id},
        )
    )


@app.delete("/customers/{customer_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_customer(customer_id: int, db: ScopedDB = Depends(get_scoped_db)) -> None:
    cur = db.execute(
        f"DELETE FROM customers WHERE id = :id AND tenant_id = {SCOPE_MARKER}",
        {"id": customer_id},
    )
    if cur.rowcount == 0:
        db.rollback()
        raise HTTPException(status_code=404, detail="Customer not found")
    db.commit()


@app.exception_handler(UnsafeQuery)
async def unsafe_query_handler(request: Request, exc: UnsafeQuery) -> JSONResponseType:
    from fastapi.responses import JSONResponse

    return JSONResponse(status_code=500, content={"detail": str(exc)})


JSONResponseType = Any  # forward-compat alias used above

